void DrawProtogen(void) {
	if(HUB75_StartDrawing()) {
		HUB75_CopyFrame((uint16_t*)protogen_face_1, HUB75_PANEL_HEIGHT * HUB75_PANEL_WIDTH);
		DrawEmblem(0, 0, 0x1F);
		HUB75_StopDrawing();
	}
}

//ALWAYS put it between StartDrawing - StopDrawing
void DrawEmblem(uint8_t r, uint8_t g, uint8_t b) {
	for (int i = 31; i >= 19; i--) {
		for (int j = 0; j <= 4; j++) {
			HUB75_SetPixel(i, j, r, g, b);
			HUB75_SetPixel(i, 127 - j, r, g, b);
		}
	}

	for (int i = 31; i >= 20; i--) {
		for (int j = 5; j <= 6; j++) {
			HUB75_SetPixel(i, j, r, g, b);
			HUB75_SetPixel(i, 127 - j, r, g, b);
		}
	}

	for (int i = 31; i >= 21; i--) {
		for (int j = 7; j <= 8; j++) {
			HUB75_SetPixel(i, j, r, g, b);
			HUB75_SetPixel(i, 127 - j, r, g, b);
		}
	}

	for (int i = 31; i >= 22; i--) {
		for (int j = 9; j <= 9; j++) {
			HUB75_SetPixel(i, j, r, g, b);
			HUB75_SetPixel(i, 127 - j, r, g, b);
		}
	}

	for (int i = 31; i >= 23; i--) {
		for (int j = 10; j <= 10; j++) {
			HUB75_SetPixel(i, j, r, g, b);
			HUB75_SetPixel(i, 127 - j, r, g, b);
		}
	}

	for (int i = 31; i >= 24; i--) {
		for (int j = 11; j <= 11; j++) {
			HUB75_SetPixel(i, j, r, g, b);
			HUB75_SetPixel(i, 127 - j, r, g, b);
		}
	}

	for (int i = 31; i >= 26; i--) {
		for (int j = 12; j <= 12; j++) {
			HUB75_SetPixel(i, j, r, g, b);
			HUB75_SetPixel(i, 127 - j, r, g, b);
		}
	}

	for (int i = 31; i >= 28; i--) {
		for (int j = 13; j <= 13; j++) {
			HUB75_SetPixel(i, j, r, g, b);
			HUB75_SetPixel(i, 127 - j, r, g, b);
		}
	}
}

void DrawColorSin(void) {
	if (lastMillis + maxPositionMillis < HAL_GetTick()) {
		if(HUB75_StartDrawing()) {
			for (uint16_t col = 0; col < HUB75_PANEL_WIDTH; col++)
			{
				int sinRow = sin(((double)(col + position) / HUB75_PANEL_WIDTH) * 3.1415 * 6) * (HUB75_PANEL_HEIGHT / 2) + (HUB75_PANEL_HEIGHT / 2);

				for (uint16_t row = 0; row < HUB75_PANEL_HEIGHT; row++)
				{
					if (row == sinRow) {
					    HUB75_SetPixel(row, col, 31, 31, 31);
					}
					else {
					    if(row > sinRow) {

					        int v = col % 64;

					        float h = (v / 64.0f) * 360.0f;
					        float s = 1.0f;
					        float val = (row / 16.0f);

					        float c = val * s;
					        float x = c * (1 - fabsf(fmodf(h / 60.0f, 2) - 1));
					        float m = val - c;

					        float r1, g1, b1;

					        if (h < 60)       { r1 = c; g1 = x; b1 = 0; }
					        else if (h < 120) { r1 = x; g1 = c; b1 = 0; }
					        else if (h < 180) { r1 = 0; g1 = c; b1 = x; }
					        else if (h < 240) { r1 = 0; g1 = x; b1 = c; }
					        else if (h < 300) { r1 = x; g1 = 0; b1 = c; }
					        else              { r1 = c; g1 = 0; b1 = x; }

					        uint8_t r = (uint8_t)((r1 + m) * 31.0f);
					        if (r > 31) r = 31;

					        uint8_t g = (uint8_t)((g1 + m) * 31.0f);
					        if (g > 31) g = 31;

					        uint8_t b = (uint8_t)((b1 + m) * 31.0f);
					        if (b > 31) b = 31;

					        HUB75_SetPixel(row, col, r, g, b);
					    }
					    else {
					        HUB75_SetPixel(row, col, 0, 0, 0);
					    }
					}
				}
			}
			HUB75_StopDrawing();
		}

		if(NOKIA_StartDataPrepare()) {
			for (uint16_t col = 0; col < NOKIA_PANEL_WIDTH; col++)
			{
				int sinRow = sin(((double)(col + position) / NOKIA_PANEL_WIDTH) * 3.1415 * 6) * (NOKIA_PANEL_HEIGHT / 2) + (NOKIA_PANEL_HEIGHT / 2);

				for (uint16_t row = 0; row < NOKIA_PANEL_HEIGHT; row++) {
					if (row == sinRow) {
						NOKIA_SetPixel(col, row, true);
					}
					else {
						NOKIA_SetPixel(col, row, false);
					}
				}
			}

			NOKIA_SetLine(5, 1, 50, 20, true);
			NOKIA_SetRect(20, 20, 30, 40, false, true);
			NOKIA_SetCircle(50, 30, 5, true, 5);
			NOKIA_SetStr("A quick brown fox jumpS over the lazy doG!\n1234567890\\./", 10, 0, true, true, true);

			NOKIA_StopDataPrepare();
			NOKIA_SendData();
		}

		lastMillis = HAL_GetTick();
		position++;
		if (position >= HUB75_PANEL_WIDTH) {
			position = 0;
		}
	}
}
